import{_ as E,l as o,o as e,c as i,v as t,p as s,x as r,d as l,i as B,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"MarS 生成式订单流","description":"","frontmatter":{"title":"MarS 生成式订单流","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mars-generative-sim.md","filePath":"quant/mars-generative-sim.md","lastUpdated":1789023840000}'),p={name:"quant/mars-generative-sim.md"};function A(h,a,m,c,u,k){const n=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="mars-生成式订单流" tabindex="-1">MarS 生成式订单流 <a class="header-anchor" href="#mars-生成式订单流" aria-label="Permalink to &quot;MarS 生成式订单流&quot;">​</a></h1><div class="epigraph"><p>若能对市场消息的联合分布建立生成模型，仿真就不必再靠手写代理规则去拼出价差与成串；检验标准变成生成轨迹是否复制 stylized facts，以及插入需求后冲击是否像真的。</p><footer>—— 对照 Li 等人对 MarS 生成式市场仿真引擎的表述，以及生成式订单流研究把限价簿当作序列数据的路线</footer></div><p><a href="/quant/abides-simulation">ABIDES</a> 用规则代理内生出消息。<a href="/quant/neural-hawkes-orderflow">Neural Hawkes</a> 用强度生成事件类型与时间，簿会计另算。MarS（Market Simulation engine powered by a generative foundation model）把更长的市场消息序列当作可学习的生成对象：在历史轨迹上训练一个大模型，再采样出新的订单流或在给定上下文中续写。Li 等人把这一引擎写成可插入「什么-如果」需求的研究工具——例如在生成世界里加入一组额外的买卖，观察随后的簿与价格。它是数据驱动的仿真，不是又一个 DeepLOB 判别器。本篇写生成对象、评价协议、以及生成器训练窗对下游策略评估的污染。生成式仿真不能证明实盘可交易性，只能在设定内做反事实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写代理很难同时对齐价差、深度、成交成串、长记忆波动和冲击凹性。每补一个 stylized fact，往往拆掉另一个。生成模型直接对准消息的经验分布，理论上可以同时复制多个边际与短程依赖。问题是对象定义：生成的是成交价序列、是 BBO、还是带量的限价/撤/成消息？对象越靠近 L3，越能支撑执行实验，也越容易学到特定交易所的报文指纹与特定年份的参与者结构，外推脆弱。</p><p>第二个问题是条件。无条件采样给出「像某市场的一天」；条件采样给出「在今天上午已实现路径之后继续」。策略评估需要后者，而且必须保证条件只含决策时点之前的消息。若续写时看见了下午的真实路径，生成器变成泄漏的插值器。这与判别式 LOB 的<a href="/quant/deep-lob-leakage">泄漏</a>同一逻辑，只是发生在采样器里。</p><h3 id="token-化市场消息" tabindex="-1">token 化市场消息 <a class="header-anchor" href="#token-化市场消息" aria-label="Permalink to &quot;token 化市场消息&quot;">​</a></h3><p>生成式引擎通常把事件编码成离散 token：类型、方向、相对价格档、量桶、时间间隔桶。桶太粗，冲击实验分不出一档与两档；桶太细，序列极长，长程依赖难学。时间间隔必须进入 token，否则采样只有事件顺序没有日历钟，无法与真实延迟或与 ABIDES 的唤醒对齐。价格应相对当时中点，否则生成器记忆绝对价格水平，换一年就坏。这些设计选择决定引擎能回答哪类反事实，应写在方法而不是附录。</p><p><span class="marginnote">「基础模型」指可在多标的、多日上预训练再条件化的生成器，不指它已经理解了经济结构。容量大只说明能拟合训练消息的联合，也包括能拟合训练期里某只产品的微观结构噪声。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>训练窗。</strong> 严格按日历切开。生成器只在训练日上最大似然（或等效的下一 token 损失）。验证日只用来早停与选桶边界。测试日的真实消息不得进入预训练，也不得进入「为了让生成更像测试日」的适配。下游若要用生成轨迹评估某个执行策略，该策略的超参不得在同一测试日的生成轨迹上搜——否则策略过拟合生成器的指纹，而生成器又过拟合训练协议，两层乐观相乘。</p><p><strong>评价分三层，必须同时报告。</strong> （1）无条件 stylized facts：价差分布、深度、成交间隔的重尾、符号自相关、波动聚类。（2）条件续写：给定上午真实簿，下午生成路径与真实下午在上述统计上的距离，以及价格水平是否发散。（3）冲击响应：在生成世界里插入一组外生的有符号需求，估计临时与永久冲击，并与真实市场的估计对照，见平方根冲击一类事实。只报（1）不够：无条件像，条件续写仍可能在插入需求后崩掉，因为训练数据里很少见到「你这种规模」的外生流。</p><h3 id="插入需求与不可识别" tabindex="-1">插入需求与不可识别 <a class="header-anchor" href="#插入需求与不可识别" aria-label="Permalink to &quot;插入需求与不可识别&quot;">​</a></h3><p>生成器学的是观测到的消息分布。观测到的大单已经被当时的市场消化，反事实「再加一笔同样的单」不是从同一分布里多抽一个 token 那么简单——环境会变。MarS 类引擎若提供插入接口，必须说明插入是条件干预（改写后续采样的前缀）还是仅在回放上叠加。前者更接近仿真，后者更接近磁带。二者都不是随机对照实验。应报告插入规模相对于当时深度的比例，并避免插入训练里从未出现的极端规模却声称冲击曲线可信。</p><p>与 ABIDES 对照：在规则仿真里插入是明确的因果（种群固定、多一个代理）；在生成式世界里插入是对学到的条件分布做外推。外推失败时路径会离开真实簿的流形（负深度、交叉的买卖、不合法的时间间隔）。合法性约束（价差为正、量非负、撮合规则）应硬编码在解码器或拒绝采样里，不能指望 softmax 自己遵守交易所规则。</p><p><span class="marginnote">用测试日的真实下午去微调生成器，再在「生成的下午」上评估策略，是循环。看起来像样本外仿真，信息集已经含测试日。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自回归生成把 \\(P(\\text{消息}_{1:n})\\) 拆成下一 token 条件概率。短程成串（Hawkes 式）容易被局部上下文捕获；长程的日内季节性需要位置或时钟特征，否则上午开盘的脉冲会被摊成均匀的高强度。对抗或扩散式生成可以一次出一段轨迹，但插入干预更难定义。无论哪一种，似然高不等于冲击对：似然主要由高频的小撤单与心跳式事件主导，真正决定 P&amp;L 的大单是稀事件。评价必须对大单与 BBO 变化单独加权，不能只报 token 准确率。</p><p>生成器会把训练期的参与者生态冻住。真实市场在新做市商进入、费率改、制度改之后分布会变。用 2021 年训的引擎去仿真 2026 年的插入实验，概念漂移与<a href="/quant/cross-market-transfer-learning">跨市场迁移</a>同类。应在制度断点处切开预训练，并承认引擎没有对未见到的规则的外推权。A 股涨跌停与集合竞价必须作为合法状态出现在 token 里，否则生成连续竞价去评估开盘，是在错误的产品上做实验。</p><h3 id="和判别-lob、和-hawkes-的关系" tabindex="-1">和判别 LOB、和 Hawkes 的关系 <a class="header-anchor" href="#和判别-lob、和-hawkes-的关系" aria-label="Permalink to &quot;和判别 LOB、和 Hawkes 的关系&quot;">​</a></h3><p>DeepLOB 估 \\(P(\\text{中点方向}\\mid\\text{窗})\\)；Neural Hawkes 估 \\(\\lambda(\\text{类型}\\mid\\text{历史})\\)；MarS 估整段消息的联合。联合生成可以派生前两者：对生成轨迹统计方向命中或拟合强度。反过来，把判别模型的梯度用来「引导」生成，会把判别器的泄漏带进仿真。保持生成器训练独立，是为了让仿真仍能当下游的测试床，而不是当另一层过拟合。</p><p>计算上，采样足够多的轨迹才能谈冲击曲线的误差棒。一条漂亮的生成日只能当示意。报告应给出轨迹数、拒绝采样率（因违反簿规则被丢掉的比例）。拒绝率高说明模型常离开合法流形，此时冲击数字不可信。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>生成式仿真不能替代实盘或纸交易：没有自己的延迟、没有真实对手的学习、没有交易所的隐性规则变更。它适合：在可控插入下比较执行算法、做压力情景的定性图、为 ABIDES 的代理规则提供「像真」的对照。它不适合：直接输出一个交易信号的夏普、或声称已经解决容量估计——容量还依赖真实对手如何对你反应，生成器最多给出训练生态下的近似。</p><p>不要把生成轨迹与真实测试日混合成一条「更长的样本」去做回测。不要在生成器的提示里放入策略将要评估的未来信息。不要用未说明桶边界与合法性约束的引擎作为论文的唯一市场。开源权重若含训练日历之外的数据，使用者有责任重新按自己的测试年切割，而不能把公开权重当无污染先验。</p><p>与 ABIDES 的选择：需要可解释的规则与明确插入因果时用代理仿真；需要贴近经验消息分布、愿意放弃规则透明度时用生成式。严肃研究应二者都跑，只信同号的结论。成本与数据许可往往决定你实际能跑哪一个，但那是资源约束，不是科学上哪一个已经胜出。</p><p><span class="marginnote">生成器复制了训练期的拥挤与冲击，不意味着它复制了你加入之后的拥挤。自我影响越大，生成式反事实越偏离训练支持。大单实验应标成外推，并与解析冲击上界对照。</span></p>',27)),(e(),s(d,null,{default:r(()=>[B(n,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIST%5B%22%E8%AE%AD%E7%BB%83%E6%97%A5%E6%B6%88%E6%81%AF%22%5D%20--%3E%20TOK%5B%22%E7%B1%BB%E5%9E%8B%20%2F%20%E6%A1%A3%20%2F%20%E9%87%8F%20%2F%20%E9%97%B4%E9%9A%94%20token%22%5D%0A%20%20TOK%20--%3E%20GEN%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E6%88%96%E7%AD%89%E4%BB%B7%E7%94%9F%E6%88%90%E5%99%A8%22%5D%0A%20%20CTX%5B%22%E5%86%B3%E7%AD%96%E6%97%B6%E7%82%B9%E4%B9%8B%E5%89%8D%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%89%8D%E7%BC%80%22%5D%20--%3E%20GEN%0A%20%20GEN%20--%3E%20TRAJ%5B%22%E5%90%88%E6%B3%95%E7%BA%A6%E6%9D%9F%E4%B8%8B%E7%9A%84%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20TRAJ%20--%3E%20SF%5B%22stylized%20facts%22%5D%0A%20%20TRAJ%20--%3E%20IMP%5B%22%E6%8F%92%E5%85%A5%E9%9C%80%E6%B1%82%E5%90%8E%E7%9A%84%E5%86%B2%E5%87%BB%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20SF%20--%3E%20GATE%5B%22%E4%B8%8E%E7%9C%9F%E5%AE%9E%E5%AF%B9%E7%85%A7%3B%20%E6%8B%92%E7%BB%9D%E7%8E%87%22%5D%0A%20%20IMP%20--%3E%20GATE%0A%20%20GATE%20--%3E%20USE%5B%22%E4%BB%85%E5%9C%A8%E9%80%9A%E8%BF%87%E5%90%8E%E5%81%9A%E6%89%A7%E8%A1%8C%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MarS 一类生成式引擎从历史消息学习联合分布，用条件续写与插入需求做数据驱动仿真，与 ABIDES 的规则代理互为对照而不是替代。</li><li>训练、验证、测试必须按日历切开；token 化要含时间间隔与相对价格，并硬约束合法簿。</li><li>评价至少覆盖无条件 stylized facts、条件续写、冲击响应；token 准确率会被小事件主导。</li><li>插入是外推。测试日微调、提示含未来、把生成轨迹拼进真实回测，都会污染下游评估。</li><li>出处：Li et al., MarS 生成式市场仿真引擎；点过程生成对照 Mei and Eisner, <em>NeurIPS</em>, 2017；规则仿真对照 Byrd, Hybinette and Balch, ABIDES。判别式 LOB 基准见 Zhang, Zohren and Roberts, <em>IEEE TSP</em>, 2019。</li></ul>',2))])}const D=E(p,[["render",A]]);export{S as __pageData,D as default};
